style.css:
@-moz-document domain("pony.town") {
/* BACKGROUND - purple-blue aurora like Carrd */
  html, body {
    background:
      radial-gradient(500px 300px at 15% 5%, rgba(126,200,255,.55), transparent 60%),
      radial-gradient(600px 350px at 85% 10%, rgba(139,108,255,.6), transparent 60%),
      radial-gradient(400px 500px at 50% 100%, rgba(74,42,138,.7), transparent 60%),
      radial-gradient(1px 1px at 20% 30%, #fff 50%, transparent 51%),
      radial-gradient(1px 1px at 70% 20%, #fff 50%, transparent 51%),
      radial-gradient(1px 1px at 85% 75%, #fff 50%, transparent 51%),
      linear-gradient(180deg, #2a1a6e 0%, #6a5cff 30%, #3b82f6 55%, #4a2a8a 100%) !important;
    background-attachment: fixed !important;
    color: #efe8ff !important;
  }
  .container, .container-fluid, main, #app { background: transparent !important; }

  /* NAV - translucent glass */
  .navbar, nav.navbar, header {
    background: rgba(90, 74, 168, .55) !important;
    border-bottom: 1.5px solid rgba(255,255,255,.65) !important;
    backdrop-filter: blur(10px) !important;
  }
  .navbar a, .navbar .nav-link { color: #fff !important; font-weight: 700 !important; }
  .navbar .nav-link.active, .navbar .nav-link:hover {
    background: rgba(255,255,255,.18) !important;
    border-radius: 999px !important;
  }

  /* PANELS - GLASS like Carrd */
  .card, .card-body, .row, .col,
  div[class*="character"], div[class*="editor"] {
    background: linear-gradient(180deg,
      rgba(201,167,255,.45) 0%,
      rgba(142,200,255,.38) 25%,
      rgba(90,74,168,.62) 70%,
      rgba(74,42,138,.68) 100%) !important;
    border: 1.5px solid rgba(255,255,255,.85) !important;
    border-radius: 24px !important;
    color: #fff !important;
    box-shadow:
      0 0 0 2px rgba(201,167,255,.35),
      0 0 32px rgba(201,167,255,.55),
      0 0 48px rgba(126,200,255,.35) !important;
    backdrop-filter: blur(10px) !important;
  }

  /* TABS - outline pills like ✦ about ✦ */
  .nav-tabs, .nav-pills { border-bottom: 1px solid rgba(255,255,255,.5) !important; }
  .nav-tabs .nav-link, .nav-pills .nav-link {
    background: transparent !important;
    color: #fff !important;
    border: 1.5px solid rgba(255,255,255,.85) !important;
    border-radius: 999px !important;
    margin: 3px !important;
  }
  .nav-tabs .nav-link.active, .nav-pills .nav-link.active {
    background: rgba(255,255,255,.22) !important;
    box-shadow: 0 0 16px rgba(255,255,255,.5) !important;
  }

  label, legend, h1, h2, h3, h4, h5, p, span, small {
    color: #fff !important;
    text-shadow: 0 1px 8px rgba(42,26,110,.9) !important;
  }

  /* Inputs - translucent glass */
  .form-control, .form-select, input, textarea, select,
  .input-group-text, .dropdown-menu {
    background: rgba(255,255,255,.18) !important;
    border: 1.5px solid rgba(255,255,255,.85) !important;
    border-radius: 14px !important;
    color: #fff !important;
  }
  .form-control::placeholder { color: rgba(255,255,255,.75) !important; }
  .dropdown-item { color: #3a2a6d !important; background: #fff !important; }

  /* BUTTONS - outline pills ✦ */
  .btn, button {
    background: transparent !important;
    color: #fff !important;
    border: 1.5px solid rgba(255,255,255,.9) !important;
    border-radius: 999px !important;
    font-weight: 700 !important;
    box-shadow: 0 0 14px rgba(255,255,255,.25) !important;
  }
  .btn:hover, button:hover {
    background: rgba(255,255,255,.22) !important;
    box-shadow: 0 0 20px rgba(255,255,255,.55) !important;
  }

  input[type="range"] { accent-color: #fff !important; }
  canvas {
    border: 1.5px solid rgba(255,255,255,.85) !important;
    border-radius: 24px !important;
    box-shadow: 0 0 24px rgba(201,167,255,.5) !important;
  }
}
